function unique(values) {
  return [...new Set(values)].sort((a, b) => a.localeCompare(b, "zh-CN"));
}

function githubUrl(skill) {
  if (!DATA.repoBase) return "";
  return `${DATA.repoBase}/tree/main/skills/${skill.slug}`;
}

function teammateFor(skill) {
  return DATA.teammates.find((teammate) => teammate.id === skill.teammateId) || DATA.teammates[0];
}

function audienceFor(id) {
  return DATA.audiences.find((audience) => audience.id === id);
}

function packFor(id) {
  return DATA.solutionPacks.find((pack) => pack.id === id);
}

function teammateById(id) {
  return DATA.teammates.find((teammate) => teammate.id === id);
}

function skillFor(slug) {
  return DATA.skills.find((skill) => skill.slug === slug);
}

function skillSearchText(skill) {
  return [
    skill.slug,
    skill.title,
    skill.category,
    skill.platform,
    skill.signal,
    skill.business,
    skill.teammateName,
    skill.teammateTitle,
    skill.teammateDepartment,
    skill.teammatePersonality,
    skill.inputHint,
    skill.outputHint,
    skill.difficulty,
    ...skill.valueTags,
    ...skill.workflowChain,
    ...skill.roles,
    ...skill.scenes,
    ...skill.audienceTags
  ].join(" ").toLowerCase();
}

function coerceMinStars(raw) {
  const value = Number(raw);
  return Number.isFinite(value) ? value : 0;
}

function presetFromUrl() {
  const params = new URLSearchParams(window.location.search);
  const preset = {};
  if (params.has("skill")) preset.skill = params.get("skill") || "";
  if (params.has("query")) preset.query = params.get("query") || "";
  if (params.has("audience")) preset.audience = params.get("audience") || "all";
  if (params.has("pack")) preset.pack = params.get("pack") || "all";
  if (params.has("teammate")) preset.teammate = params.get("teammate") || "all";
  if (params.has("category")) preset.category = params.get("category") || "全部分类";
  if (params.has("market")) preset.market = params.get("market") || "all";
  if (params.has("role")) preset.role = params.get("role") || "全部岗位";
  if (params.has("minStars")) preset.minStars = coerceMinStars(params.get("minStars"));
  if (params.has("status")) preset.status = params.get("status") || "all";
  if (params.has("sort")) preset.sort = params.get("sort") || "score";
  return preset;
}

function collabPresetFromUrl() {
  const params = new URLSearchParams(window.location.search);
  return {
    chain: params.get("collabChain") || "all",
    teammate: params.get("collabTeammate") || "all",
    audience: params.get("collabAudience") || "all"
  };
}

function hasPreset(preset) {
  return Object.keys(preset).length > 0;
}

function scrollToAnchorTarget() {
  if (!window.location.hash) return;
  const target = document.querySelector(window.location.hash);
  if (!target) return;
  requestAnimationFrame(() => {
    target.scrollIntoView({ behavior: "smooth", block: "start" });
  });
}

function packSkillMatches(skill, pack) {
  if (!pack) return true;
  const text = skillSearchText(skill);
  return pack.teammateIds.includes(skill.teammateId)
    || pack.categories.includes(skill.category)
    || pack.keywords.some((keyword) => text.includes(keyword.toLowerCase()));
}

function syncControls() {
  els.teammateFilter.value = state.teammate;
  els.categoryFilter.value = state.category;
  els.marketFilter.value = state.market;
  els.roleFilter.value = state.role;
  els.starFilter.value = String(state.minStars);
  els.statusFilter.value = state.status;
  els.sortFilter.value = state.sort;
  els.searchInput.value = state.query;
}

function syncSkillUrl(skill = "") {
  const url = new URL(window.location.href);
  if (skill) url.searchParams.set("skill", skill);
  else url.searchParams.delete("skill");
  window.history.replaceState({}, "", `${url.pathname.split('/').pop()}${url.search}${url.hash}`);
}

function syncCollabUrl() {
  const url = new URL(window.location.href);
  if (collabState.chain !== "all") url.searchParams.set("collabChain", collabState.chain);
  else url.searchParams.delete("collabChain");
  if (collabState.teammate !== "all") url.searchParams.set("collabTeammate", collabState.teammate);
  else url.searchParams.delete("collabTeammate");
  if (collabState.audience !== "all") url.searchParams.set("collabAudience", collabState.audience);
  else url.searchParams.delete("collabAudience");
  window.history.replaceState({}, "", `${url.pathname.split('/').pop()}${url.search}${url.hash}`);
}

function absoluteHref(href) {
  if (!href) return "";
  try {
    return new URL(href, window.location.href).href;
  } catch (error) {
    console.error("absolute href failed", error);
    return href;
  }
}

function currentShareOrigin() {
  if (window.location.origin && window.location.origin !== "null") return window.location.origin;
  return `${window.location.protocol}//${window.location.host}`;
}

function buildShareMarkdown(skill, publicRoutes, internalRoutes) {
  const header = [
    `# ${skill.title} 运营入口包`,
    ``,
    `- Skill Slug：\`${skill.slug}\``,
    `- 负责人：${skill.teammateName} · ${skill.teammateTitle}`,
    `- 分类：${skill.category}`,
    `- 市场星级：${skill.starsText}`,
    `- 业务价值：${skill.business}`,
    `- 核心信号：${skill.signal}`,
    ``
  ];
  const publicLines = [
    `## 对外分享入口`,
    ``,
    ...publicRoutes.flatMap((route) => [
      `### ${route.title}`,
      route.note,
      ``,
      `- 相对链接：${route.href}`,
      `- 绝对链接：${route.absoluteHref}`,
      ``
    ])
  ];
  const internalLines = [
    `## 内部工作台入口`,
    ``,
    ...internalRoutes.flatMap((route) => [
      `### ${route.title}`,
      route.note,
      ``,
      `- 相对链接：${route.href}`,
      `- 绝对链接：${route.absoluteHref}`,
      ``
    ])
  ];
  const usageLines = [
    `## 建议用法`,
    ``,
    `1. 先把主页入口发到评论区、私信或你的分发素材里。`,
    `2. 再用雷达与增强简报判断这个 Skill 下一步该补哪一段能力。`,
    `3. 最后回到发布素材包和承接漏斗，完成引流到成交的闭环。`,
    ``,
    `## 当前访问域名`,
    ``,
    `- ${currentShareOrigin() || "本地预览"}`
  ];
  return [...header, ...publicLines, ...internalLines, ...usageLines].join("\n");
}

async function copyText(text) {
  if (!text) return;
  try {
    await navigator.clipboard.writeText(text);
  } catch (error) {
    console.error("copy failed", error);
  }
}

function buildCollabPrompt(chain, linkedTeammates) {
  const teammateLine = linkedTeammates.map((teammate) => `${teammate.name}（${teammate.title}）`).join(" -> ");
  return [
    `请按这个搭班方案协同完成任务。`,
    ``,
    `业务链：${chain.title}`,
    `适合场景：${(chain.audienceNames || []).join("、") || "一人公司 / 创作者 / 卖家 / 白领"}`,
    `参与同事：${teammateLine}`,
    `当前上下文 Skill：${chain.focusSkillTitle || "待补上下文 Skill"}`,
    ``,
    `我会提供这些资料：`,
    ...((chain.inputs || []).map((item) => `- ${item}`)),
    ``,
    `希望最终产出：`,
    ...((chain.deliverables || []).map((item) => `- ${item}`)),
    ``,
    `请按这个顺序协作：`,
    ...((chain.steps || []).map((item, index) => `${index + 1}. ${item}`)),
    ``,
    `请优先关注这些成功信号：`,
    ...((chain.successSignals || []).map((item) => `- ${item}`)),
    ``,
    `风险提醒：${chain.riskNote || "先看证据，再决定要不要重投入。"}`,
    ``,
    `请在交付时给我：`,
    `1. 关键判断`,
    `2. 这条链当前最值得执行的动作`,
    `3. 需要我补充的最少资料`,
    `4. 如果继续推进，下一步该进入哪个工作台`
  ].join("\n");
}

function buildCollabBrief(chain, linkedTeammates, focusSkill) {
  const skillLine = focusSkill ? `${focusSkill.title} · ${focusSkill.starsText}` : "待补上下文 Skill";
  return [
    `# ${chain.title} 协作简报`,
    ``,
    `- 搭班方案类型：${chain.kicker}`,
    `- 当前上下文 Skill：${skillLine}`,
    `- 适合场景：${(chain.audienceNames || []).join("、") || "一人公司 / 创作者 / 卖家 / 白领"}`,
    `- 参与同事：${linkedTeammates.map((teammate) => `${teammate.name}（${teammate.title}）`).join(" -> ")}`,
    `- 触发条件：${chain.trigger}`,
    `- 风险提醒：${chain.riskNote || "先看证据，再决定要不要重投入。"}`,
    ``,
    `## 需要准备`,
    ...((chain.inputs || []).map((item) => `- ${item}`)),
    ``,
    `## 预期产出`,
    ...((chain.deliverables || []).map((item) => `- ${item}`)),
    ``,
    `## 协作步骤`,
    ...((chain.steps || []).map((item, index) => `${index + 1}. ${item}`)),
    ``,
    `## 成功信号`,
    ...((chain.successSignals || []).map((item) => `- ${item}`)),
    ``,
    `## 推荐入口`,
    `- 起点：${chain.startHref || ""}`,
    `- 执行线：${chain.routeHref || ""}`,
    `- 下载页：${chain.packHref || ""}`,
    `- 作战板：${chain.growthHref || ""}`,
    `- 素材包：${chain.launchHref || ""}`,
    `- 承接页：${chain.conversionHref || ""}`
  ].join("\n");
}

function applyPreset(preset = {}, options = {}) {
  const shouldScroll = options.scroll !== false;
  const targetSelector = options.targetSelector || ".filters-section";
  state.skill = preset.skill || "";
  state.query = preset.query || "";
  state.audience = preset.audience || "all";
  state.pack = preset.pack || "all";
  state.teammate = preset.teammate || "all";
  state.category = preset.category || "全部分类";
  state.market = preset.market || "all";
  state.role = preset.role || "全部岗位";
  state.minStars = preset.minStars || 0;
  state.status = preset.status || "all";
  state.sort = preset.sort || "score";
  syncControls();
  renderSkills();
  if (shouldScroll) {
    document.querySelector(targetSelector)?.scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

function clearGuidedContext() {
  state.skill = "";
  state.audience = "all";
  state.pack = "all";
  syncSkillUrl("");
}

function renderOptions() {
  const categories = ["全部分类", ...DATA.categories.map((item) => item.name)];
  const roles = ["全部岗位", ...unique(DATA.skills.flatMap((item) => item.roles))];
  els.teammateFilter.innerHTML = [
    `<option value="all">全部团队成员</option>`,
    ...DATA.teammates.map((teammate) => `<option value="${teammate.id}">${teammate.name} · ${teammate.title}</option>`)
  ].join("");
  els.categoryFilter.innerHTML = categories.map((item) => `<option value="${item}">${item}</option>`).join("");
  els.roleFilter.innerHTML = roles.map((item) => `<option value="${item}">${item}</option>`).join("");
}

function renderAudiences() {
  els.audienceBoard.innerHTML = DATA.audiences.map((audience) => {
    const matched = DATA.skills.filter((skill) => skill.audienceTags.includes(audience.id));
    const packaged = matched.filter((skill) => skill.hasPackage).length;
    return `
      <button class="audience-card" type="button" data-audience="${audience.id}">
        <span class="card-kicker">我是谁</span>
        <h3>${audience.name}</h3>
        <p class="signal">${audience.headline}</p>
        <p class="small-muted">${audience.promise}</p>
        <div class="value-tags">
          ${audience.keywords.slice(0, 5).map((tag) => `<span class="pill">${tag}</span>`).join("")}
        </div>
        <p class="small-muted">${matched.length} 个匹配 Skill，${packaged} 个当前有下载包。</p>
      </button>
    `;
  }).join("");
  els.audienceBoard.querySelectorAll("[data-audience]").forEach((button) => {
    button.addEventListener("click", () => {
      state.audience = button.dataset.audience;
      state.pack = "all";
      state.query = "";
      state.teammate = "all";
      state.category = "全部分类";
      state.market = "all";
      state.role = "全部岗位";
      state.minStars = 0;
      state.status = "all";
      state.sort = "score";
      syncControls();
      renderSkills();
      document.querySelector(".filters-section").scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });
}

