function renderCompanyCollab() {
  if (!els.companyCollabGrid) return;
  const chainOptions = DATA.companyCollabChains || [];
  const teammateOptions = unique(DATA.companyCollabChains.flatMap((chain) => chain.teammateIds || []))
    .map((id) => teammateById(id))
    .filter(Boolean);
  const audienceOptions = unique(DATA.companyCollabChains.flatMap((chain) => chain.audienceIds || []))
    .map((id) => audienceFor(id))
    .filter(Boolean);
  if (els.collabTeammateFilter) {
    els.collabTeammateFilter.innerHTML = [
      `<option value="all">全部协作岗位</option>`,
      ...teammateOptions.map((teammate) => `<option value="${teammate.id}">${teammate.name} · ${teammate.title}</option>`)
    ].join("");
    els.collabTeammateFilter.value = collabState.teammate;
  }
  if (els.collabAudienceFilter) {
    els.collabAudienceFilter.innerHTML = [
      `<option value="all">全部工作场景</option>`,
      ...audienceOptions.map((audience) => `<option value="${audience.id}">${audience.name}</option>`)
    ].join("");
    els.collabAudienceFilter.value = collabState.audience;
  }
  const chains = DATA.companyCollabChains.filter((chain) => {
    if (collabState.chain !== "all" && chain.id !== collabState.chain) return false;
    if (collabState.teammate !== "all" && !(chain.teammateIds || []).includes(collabState.teammate)) return false;
    if (collabState.audience !== "all" && !(chain.audienceIds || []).includes(collabState.audience)) return false;
    return true;
  });
  if (els.companyCollabSummary) {
    const summary = [`当前显示 ${chains.length} 种搭班方案`];
    if (collabState.chain !== "all") {
      const chain = chainOptions.find((item) => item.id === collabState.chain);
      if (chain) summary.push(`业务链：${chain.title}`);
    }
    if (collabState.teammate !== "all") {
      const teammate = teammateById(collabState.teammate);
      if (teammate) summary.push(`岗位：${teammate.name} · ${teammate.title}`);
    }
    if (collabState.audience !== "all") {
      const audience = audienceFor(collabState.audience);
      if (audience) summary.push(`场景：${audience.name}`);
    }
    if (collabState.teammate === "all" && collabState.audience === "all") {
      summary.push("覆盖内容增长、跨境卖家、办公提效、一人公司经营等高需求场景。");
    }
    els.companyCollabSummary.textContent = summary.join("，");
  }
  if (!chains.length) {
    els.companyCollabGrid.innerHTML = `
      <article class="collab-card">
        <span class="card-kicker">暂无匹配</span>
        <h3>当前筛选下没有搭班方案</h3>
        <p class="signal">可以先重置搭班方式，或者换一个岗位 / 工作场景重新看。</p>
        <div class="card-actions">
          <button class="card-action" type="button" data-reset-collab-grid="true">重置搭班方式</button>
        </div>
      </article>
    `;
    els.companyCollabGrid.querySelector("[data-reset-collab-grid]")?.addEventListener("click", () => {
      collabState.chain = "all";
      collabState.teammate = "all";
      collabState.audience = "all";
      syncCollabUrl();
      renderCompanyCollab();
    });
    return;
  }
  els.companyCollabGrid.innerHTML = chains.map((chain) => `
    <article class="collab-card">
      <span class="card-kicker">${chain.kicker}</span>
      <h3>${chain.title}</h3>
      <p class="signal">${chain.summary}</p>
      <div class="collab-chain">
        ${chain.teammates.map((teammate, index) => `
          ${index ? `<span class="chain-arrow">→</span>` : ""}
          <a class="chain-node" href="${teammate.href}" style="--teammate: ${teammate.color}">
            <span class="teammate-avatar small">${teammate.avatar}</span>
            <span>${teammate.name}</span>
          </a>
        `).join("")}
      </div>
      <p class="collab-note">${chain.trigger}</p>
      <div class="metric-strip">
        ${[`${chain.skillCount} 个相关 Skill`, `${chain.fiveCount} 个五星优先`, `${chain.packagedCount} 个可下载`]
          .concat(chain.metrics || [])
          .map((item) => `<span class="metric-chip">${item}</span>`)
          .join("")}
      </div>
      <div class="value-tags">
        ${(chain.deliverables || []).map((item) => `<span class="pill">${item}</span>`).join("")}
      </div>
      <p class="small-muted">${chain.handoff}</p>
      <p class="small-muted">${chain.contextNote || ""}</p>
      <div class="nav-chip-row">
        ${chain.landingHref ? `<a class="nav-chip" href="${chain.landingHref}">${chain.landingCta || "看专题页"}</a>` : ""}
        ${chain.growthHref ? `<a class="nav-chip" href="${chain.growthHref}">${chain.growthCta || "去作战板"}</a>` : ""}
        ${chain.launchHref ? `<a class="nav-chip" href="${chain.launchHref}">${chain.launchCta || "去素材包"}</a>` : ""}
        ${chain.conversionHref ? `<a class="nav-chip" href="${chain.conversionHref}">${chain.conversionCta || "去承接页"}</a>` : ""}
      </div>
      <div class="card-actions">
        <button class="github-link" type="button" data-open-collab-chain="${chain.id}">看这条链怎么运转</button>
        <a class="card-action" href="${chain.startHref}">${chain.startCta}</a>
        ${chain.bundleDownload ? `<a class="github-link" href="${chain.bundleDownload}" download>${chain.bundleLabel || "下载链路合集包"}</a>` : ""}
        ${chain.routeHref ? `<a class="github-link" href="${chain.routeHref}">${chain.routeCta}</a>` : ""}
        ${chain.packHref ? `<a class="github-link" href="${chain.packHref}">${chain.packLabel || "看这条链的下载包"}</a>` : ""}
      </div>
    </article>
  `).join("");
  els.companyCollabGrid.querySelectorAll("[data-open-collab-chain]").forEach((button) => {
    button.addEventListener("click", () => openCollabChain(button.dataset.openCollabChain));
  });
}

function renderPacks() {
  els.packGrid.innerHTML = DATA.solutionPacks.map((pack) => {
    const matched = sortedSkills(DATA.skills.filter((skill) => packSkillMatches(skill, pack)));
    const examples = matched.slice(0, 3);
    const packaged = matched.filter((skill) => skill.hasPackage).length;
    return `
      <button class="pack-card" type="button" data-pack="${pack.id}">
        <span class="card-kicker">开箱即用包</span>
        <h3>${pack.title}</h3>
        <p class="signal">${pack.summary}</p>
        <p class="small-muted">${pack.promise}</p>
        <ul class="pack-list">
          ${examples.map((skill) => `<li>${skill.teammateName}：${skill.title}</li>`).join("")}
        </ul>
        <p class="small-muted">${matched.length} 个相关 Skill，${packaged} 个当前有下载包。</p>
      </button>
    `;
  }).join("");
  els.packGrid.querySelectorAll("[data-pack]").forEach((button) => {
    button.addEventListener("click", () => {
      const pack = packFor(button.dataset.pack);
      state.pack = button.dataset.pack;
      state.audience = pack?.audienceId || "all";
      state.query = "";
      state.teammate = "all";
      state.category = "全部分类";
      state.market = "all";
      state.role = "全部岗位";
      state.minStars = 0;
      state.status = "all";
      state.sort = "score";
      syncControls();
      renderSkills();
      document.querySelector(".filters-section").scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });
}

function renderFeatured() {
  const featured = DATA.featuredSkillTitles
    .map((title) => DATA.skills.find((skill) => skill.title === title))
    .filter(Boolean);
  els.featuredGrid.innerHTML = featured.map((skill) => {
    const teammate = teammateFor(skill);
    return `
      <button class="featured-card" type="button" data-open-featured="${skill.slug}">
        <span class="badge">${skill.difficulty}</span>
        <h3>${skill.title}</h3>
        <div class="teammate-mini" style="--teammate: ${teammate.color}">
          <span class="teammate-avatar small">${teammate.avatar}</span>
          <span>
            <strong>${skill.teammateName} · ${skill.teammateTitle}</strong>
            <span>${skill.teammatePersonality}</span>
          </span>
        </div>
        <p class="signal">${skill.signal}</p>
        <div class="value-tags">
          ${skill.valueTags.slice(0, 3).map((tag) => `<span class="pill">${tag}</span>`).join("")}
        </div>
      </button>
    `;
  }).join("");
  els.featuredGrid.querySelectorAll("[data-open-featured]").forEach((button) => {
    button.addEventListener("click", () => openSkill(button.dataset.openFeatured));
  });
}

function renderDemandLab() {
  const demandSkills = DATA.skills.filter((skill) => skill.category === "研究报告与咨询分析");
  const demandPackaged = demandSkills.filter((skill) => skill.hasPackage).length;
  const demandFive = demandSkills.filter((skill) => skill.stars >= 5).length;
  const overseasCount = demandSkills.filter((skill) => skill.marketScope === "海外市场").length;
  const chinaCount = demandSkills.filter((skill) => skill.marketScope === "中国市场").length;
  els.demandLabOverview.innerHTML = [
    {
      kicker: "调研总量",
      value: `${demandSkills.length}`,
      note: "当前需求验证与市场研究相关 Skill 总数"
    },
    {
      kicker: "五星优先",
      value: demandSkills.length ? `${Math.round((demandFive / demandSkills.length) * 100)}%` : "0%",
      note: `${demandFive} 个五星优先方向`
    },
    {
      kicker: "可下载",
      value: `${demandPackaged}`,
      note: "已经可以直接下载和复用的方向数量"
    },
    {
      kicker: "市场覆盖",
      value: `${chinaCount} / ${overseasCount}`,
      note: "中国市场 / 海外市场相关 Skill 数量"
    }
  ].map((item) => `
    <article class="overview-card">
      <span class="card-kicker">${item.kicker}</span>
      <strong class="overview-value">${item.value}</strong>
      <p class="small-muted">${item.note}</p>
    </article>
  `).join("");
  els.demandLabGrid.innerHTML = DATA.demandLabCards.map((card) => {
    const teammate = DATA.teammates.find((item) => item.id === card.ownerId) || DATA.teammates[0];
    const matched = DATA.skills.filter((skill) => {
      if (card.preset?.teammate && skill.teammateId !== card.preset.teammate) return false;
      if (card.preset?.category && skill.category !== card.preset.category) return false;
      if (card.preset?.market && skill.marketScope !== card.preset.market) return false;
      if (card.preset?.query) return skillSearchText(skill).includes(card.preset.query.toLowerCase());
      return true;
    });
    return `
      <button class="demand-lab-card" type="button" data-demand-desk="${card.id}">
        <span class="card-kicker">市场调研办公室</span>
        <h3>${card.title}</h3>
        <div class="teammate-mini" style="--teammate: ${teammate.color}">
          <span class="teammate-avatar small">${teammate.avatar}</span>
          <span>
            <strong>${teammate.name} · ${teammate.title}</strong>
            <span>${teammate.personality}</span>
          </span>
        </div>
        <p class="signal">${card.summary}</p>
        <p class="small-muted">${card.focus}</p>
        ${card.question ? `<p class="small-muted">${card.question}</p>` : ""}
        <div class="metric-strip">
          ${card.metrics.map((metric) => `<span class="metric-chip">${metric}</span>`).join("")}
        </div>
        ${card.handoff ? `<p class="small-muted">${card.handoff}</p>` : ""}
        <p class="small-muted">${matched.length} 个相关 Skill，点击后直接筛到这一类。</p>
      </button>
    `;
  }).join("");
  els.demandLabGrid.querySelectorAll("[data-demand-desk]").forEach((button) => {
    button.addEventListener("click", () => {
      const card = DATA.demandLabCards.find((item) => item.id === button.dataset.demandDesk);
      if (card?.workbenchHref) {
        window.location.href = card.workbenchHref;
        return;
      }
      applyPreset(card?.preset || {});
    });
  });
}

function renderTeammates() {
  const counts = new Map(DATA.teammates.map((teammate) => [teammate.id, { count: 0, five: 0 }]));
  DATA.skills.forEach((skill) => {
    const bucket = counts.get(skill.teammateId);
    if (!bucket) return;
    bucket.count += 1;
    if (skill.stars >= 5) bucket.five += 1;
  });
  els.teammateBoard.innerHTML = DATA.teammates.map((teammate) => {
    const bucket = counts.get(teammate.id) || { count: 0, five: 0 };
    const collabCount = DATA.companyCollabChains.filter((chain) => (chain.teammateIds || []).includes(teammate.id)).length;
    return `
      <article class="teammate-card" style="--teammate: ${teammate.color}">
        <div class="teammate-head">
          <span class="teammate-avatar">${teammate.avatar}</span>
          <span class="teammate-name">
            <strong>${teammate.name} · ${teammate.title}</strong>
            <span>${teammate.department}</span>
          </span>
        </div>
        <p class="teammate-quote">“${teammate.motto}”</p>
        <p class="teammate-line">${teammate.personality}</p>
        <div class="teammate-tags">
          ${teammate.bestFor.map((tag) => `<span class="pill">${tag}</span>`).join("")}
        </div>
        <p class="small-muted">${bucket.count} 个 Skill，${bucket.five} 个五星；常搭 ${collabCount} 种搭班方案；正式执行包 ${teammate.packagedSkillCount || 0} 个，规划包 ${teammate.planningSkillCount || 0} 个，待整理 ${teammate.plannedSkillCount || 0} 个。</p>
        <div class="card-actions">
          <button class="card-action" type="button" data-teammate="${teammate.id}">一键调用这位同事</button>
          <button class="github-link" type="button" data-open-collab="${teammate.id}">看搭班方案${collabCount ? `（${collabCount}）` : ""}</button>
          <button class="github-link" type="button" data-planning-teammate="${teammate.id}">看规划包</button>
          ${teammate.workbenchHref ? `<a class="github-link" href="${teammate.workbenchHref}">进入工作台</a>` : ""}
          ${teammate.landingPage ? `<a class="github-link" href="${teammate.landingPage}">进入专题页</a>` : ""}
          ${teammate.templateDownload ? `<a class="github-link" href="${teammate.templateDownload}" download>承接模板包</a>` : ""}
          ${teammate.packageDownload ? `<a class="github-link" href="${teammate.packageDownload}" download>下载员工能力包</a>` : `<span class="github-link disabled">能力包待生成</span>`}
        </div>
      </article>
    `;
  }).join("");
  els.teammateBoard.querySelectorAll("[data-teammate]").forEach((button) => {
    button.addEventListener("click", () => {
      state.teammate = button.dataset.teammate;
      els.teammateFilter.value = state.teammate;
      renderSkills();
      document.querySelector(".filters-section").scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });
  els.teammateBoard.querySelectorAll("[data-open-collab]").forEach((button) => {
    button.addEventListener("click", () => {
      collabState.chain = "all";
      collabState.teammate = button.dataset.openCollab;
      collabState.audience = "all";
      syncCollabUrl();
      renderCompanyCollab();
      document.querySelector("#company-collab")?.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });
  els.teammateBoard.querySelectorAll("[data-planning-teammate]").forEach((button) => {
    button.addEventListener("click", () => {
      const planning = DATA.skills
        .filter((skill) => skill.teammateId === button.dataset.planningTeammate && skill.packageKind === "planning")
        .sort((a, b) => b.score - a.score || a.number - b.number);
      const first = planning[0];
      if (!first) return;
      window.location.href = `./planning-center.html?teammate=${button.dataset.planningTeammate}&slug=${first.slug}`;
    });
  });
}

function renderDownloadCollections() {
  const container = els.downloadCollectionGrid;
  container.className = "accordion-container";
  
  container.innerHTML = DATA.downloadCollections.map((collection, index) => {
    const teammate = DATA.teammates.find((item) => item.id === collection.teammateId) || DATA.teammates[0];
    const matched = sortedSkills(DATA.skills.filter((skill) => {
      if (collection.preset?.teammate && skill.teammateId !== collection.preset.teammate) return false;
      if (collection.preset?.category && skill.category !== collection.preset.category) return false;
      if (collection.preset?.market && skill.marketScope !== collection.preset.market) return false;
      if (collection.preset?.status && skill.packageStatus !== collection.preset.status) return false;
      return skill.stars >= (collection.preset?.minStars || 0);
    }));
    const packaged = matched.filter((skill) => skill.hasPackage).length;
    
    const skillHTML = matched.map(skill => `
      <div class="skill-mini-card">
        <strong>${skill.name}</strong>
        <p>${skill.description}</p>
        <a class="github-link ${skill.hasPackage ? '' : 'disabled'}" ${skill.hasPackage ? `href="${teammate.packageDownload}" download` : ''}>
          ${skill.hasPackage ? '下载单项' : '私信获取'}
        </a>
      </div>
    `).join("");

    return `
      <div class="accordion-item" data-accordion-index="${index}">
        <div class="accordion-header">
          <div class="accordion-header-left">
            <h3>${collection.title}</h3>
            <p>${teammate.name} · ${teammate.department} | ${matched.length} 个相关 Skill</p>
          </div>
          <div class="accordion-icon">▼</div>
        </div>
        <div class="accordion-body">
          <div class="accordion-content">
            <p class="signal">${collection.summary}</p>
            <div class="skill-mini-list">
              ${skillHTML}
            </div>
            <div style="margin-top: 8px; display: flex; gap: 12px; align-items: center;">
              ${teammate.packageDownload ? `<a class="github-link primary" href="${teammate.packageDownload}" download>打包下载全部 (${packaged})</a>` : ''}
              ${teammate.landingPage ? `<a class="ghost-link" href="${teammate.landingPage}">查看专题页</a>` : ''}
            </div>
          </div>
        </div>
      </div>
    `;
  }).join("");

  // Add click listeners for accordion
  container.querySelectorAll('.accordion-header').forEach(header => {
    header.addEventListener('click', () => {
      const item = header.parentElement;
      const isOpen = item.classList.contains('open');
      
      // Close all others (optional: remove this if you want multiple open at once)
      container.querySelectorAll('.accordion-item').forEach(i => i.classList.remove('open'));
      
      if (!isOpen) {
        item.classList.add('open');
      }
    });
  });
}

function renderPlanningCenter() {
  const planningSkills = DATA.skills.filter((skill) => skill.packageKind === "planning");
  const topTeammates = DATA.teammates
    .map((teammate) => {
      const items = planningSkills
        .filter((skill) => skill.teammateId === teammate.id)
        .sort((a, b) => b.score - a.score || a.number - b.number);
      return {
        teammate,
        items,
        five: items.filter((skill) => skill.stars >= 5).length,
      };
    })
    .filter((entry) => entry.items.length)
    .sort((a, b) => b.items.length - a.items.length || b.five - a.five)
    .slice(0, 6);

  const fiveCount = planningSkills.filter((skill) => skill.stars >= 5).length;
  const categories = new Set(planningSkills.map((skill) => skill.category));
  const teammateCount = new Set(planningSkills.map((skill) => skill.teammateId));

  els.planningOverview.innerHTML = [
    {
      kicker: "规划包总量",
      value: `${planningSkills.length}`,
      note: "这些方向已经能下载，但更适合先验证、再决定要不要升级成正式执行包。"
    },
    {
      kicker: "五星优先",
      value: `${fiveCount}`,
      note: "最值得优先升级和运营放大的高需求方向数量。"
    },
    {
      kicker: "涉及岗位",
      value: `${teammateCount.size}`,
      note: "已经覆盖到多少位核心同事的能力待升级池。"
    },
    {
      kicker: "涉及赛道",
      value: `${categories.size}`,
      note: "当前规划包已经覆盖的高需求业务分类数量。"
    }
  ].map((item) => `
    <article class="overview-card">
      <span class="card-kicker">${item.kicker}</span>
      <strong class="overview-value">${item.value}</strong>
      <p class="small-muted">${item.note}</p>
    </article>
  `).join("");

  els.planningCollectionGrid.innerHTML = topTeammates.map((entry) => {
    const teammate = entry.teammate;
    const topSkills = entry.items.slice(0, 4);
    return `
      <article class="download-collection-card">
        <span class="card-kicker">规划作战包</span>
        <h3>${teammate.name} · ${teammate.title}</h3>
        <div class="teammate-mini" style="--teammate: ${teammate.color}">
          <span class="teammate-avatar small">${teammate.avatar}</span>
          <span>
            <strong>${teammate.name} · ${teammate.title}</strong>
            <span>${teammate.personality}</span>
          </span>
        </div>
        <p class="signal">这位同事当前有 ${entry.items.length} 个规划作战包，其中 ${entry.five} 个是五星优先，适合先做验证、打样和升级排序。</p>
        <ul class="pack-list">
          ${topSkills.map((skill) => `<li>${skill.starsText} ${skill.title}</li>`).join("")}
        </ul>
        <div class="value-tags">
          <span class="pill">规划包 ${entry.items.length} 个</span>
          <span class="pill">五星 ${entry.five} 个</span>
          <span class="pill">${(topSkills[0] || {}).category || "高需求方向"}</span>
        </div>
        <div class="collection-foot">
          <a class="card-action" href="./planning-center.html?teammate=${teammate.id}&slug=${(topSkills[0] || {}).slug || ''}">查看这位同事的规划包</a>
          <a class="github-link" href="./planning-center.html?teammate=${teammate.id}&slug=${(topSkills[0] || {}).slug || ''}">打开最高优先 Skill</a>
          ${teammate.landingPage ? `<a class="github-link" href="${teammate.landingPage}">进入专题页</a>` : ""}
        </div>
      </article>
    `;
  }).join("");
}

